/* Generated by Vite at build time. Cache only public application resources. */
const CACHE = 'kiosco-public-__CACHE_VERSION__';
const ASSETS = __PRECACHE_ASSETS__;
const DEVELOPMENT = __DEVELOPMENT__;
const scope = self.registration.scope;
const offlineURL = new URL('offline.html', scope).href;

self.addEventListener('install', (event) => {
  if (DEVELOPMENT) return;
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(
    ASSETS.map((path) => new URL(path, scope).href),
  )));
  // Updates wait until all existing windows close, preserving unfinished sales.
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    if (DEVELOPMENT) { await self.clients.claim(); return; }
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith('kiosco-public-') && key !== CACHE)
      .map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  if (DEVELOPMENT) return; // Local push testing never intercepts Vite or HMR.
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(fetch(request).catch(async () => {
      const cache = await caches.open(CACHE);
      return (await cache.match(offlineURL)) || Response.error();
    }));
    return;
  }

  // Never intercept authentication, database calls or arbitrary same-origin APIs.
  if (!ASSETS.some((path) => new URL(path, scope).href === url.href)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    return (await cache.match(request)) || fetch(request);
  })());
});

self.addEventListener('push', (event) => {
  let payload = {};
  try { payload = event.data?.json() || {}; } catch { /* Display a safe fallback. */ }
  if (!payload || typeof payload !== 'object') payload = {};
  const view = ['catalog', 'cash', 'settings'].includes(payload.view) ? payload.view : 'settings';
  const storeId = typeof payload.storeId === 'string' && /^[0-9a-f-]{36}$/i.test(payload.storeId) ? payload.storeId : '';
  event.waitUntil(self.registration.showNotification(
    typeof payload.title === 'string' ? payload.title.slice(0, 100) : 'Kiosco Express', {
      body: typeof payload.body === 'string' ? payload.body.slice(0, 300) : 'Tenés novedades en tu comercio.',
      icon: new URL('icons/icon-192.png', scope).href,
      tag: typeof payload.tag === 'string' ? payload.tag.slice(0, 150) : 'kiosco-notice',
      data: { storeId, view },
    },
  ));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const data = event.notification.data || {};
    const view = ['catalog', 'cash', 'settings'].includes(data.view) ? data.view : 'settings';
    const storeId = typeof data.storeId === 'string' && /^[0-9a-f-]{36}$/i.test(data.storeId) ? data.storeId : '';
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const existing = windows.find(client => client.url.startsWith(scope));
    if (existing) {
      // Never reload an open POS: it may contain an unfinished sale.
      existing.postMessage({ type: 'retail-push-open', storeId, view });
      await existing.focus();
    } else {
      const url = new URL('./', scope);
      if (storeId) url.hash = `push?store=${encodeURIComponent(storeId)}&view=${view}`;
      await self.clients.openWindow(url.href);
    }
  })());
});
